import Ajv from "ajv/dist/2020.js";
import addFormats from "ajv-formats";
import standalone from "ajv/dist/standalone/index.js";
import { readFileSync, writeFileSync } from "node:fs";
const ajv = new Ajv({
  strict: false,
  allErrors: true,
  code: { source: true, esm: true },
});
addFormats(ajv);
ajv.addSchema(
  JSON.parse(readFileSync("src/contracts/ai-response.schema.json", "utf8")),
  "ai",
);
ajv.addSchema(
  JSON.parse(readFileSync("src/contracts/symptom-record.schema.json", "utf8")),
  "day",
);
writeFileSync(
  "src/contracts/validators.ts",
  "// @ts-nocheck\n// Generated by scripts/compile-validators.mjs. No runtime eval.\nimport equal from 'ajv/dist/runtime/equal';\nimport ucs2length from 'ajv/dist/runtime/ucs2length';\nimport {fullFormats} from 'ajv-formats/dist/formats';\n" +
    standalone(ajv, { validEnvelope: "ai", validDay: "day" })
      .replaceAll('require("ajv/dist/runtime/equal").default', "equal")
      .replaceAll(
        'require("ajv/dist/runtime/ucs2length").default',
        "ucs2length",
      )
      .replaceAll(
        'require("ajv-formats/dist/formats").fullFormats',
        "fullFormats",
      ),
);
